def pre(vals):
    # Valid inputs: list of 0 to 6 integers, each between -10 and 10 inclusive
    if len(vals) > 6:
        return False
    for v in vals:
        if v < -10 or v > 10:
            return False
    return True

def post(vals, result):
    # Specification: result should be a list where result[k] = max(vals[0..k])
    # for each position k, with the same length as vals

    # Check length
    if len(result) != len(vals):
        return False

    # Check each position: result[k] must equal the maximum of vals[0] through vals[k]
    for k in range(len(vals)):
        expected = max(vals[0:k+1])
        if result[k] != expected:
            return False

    return True
